mapper.select:
select
    id,
    vector_id,
    content,
    metadata,
    (1 - (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.commons.support.vector.PgVectorTypeHandler})) as score,
    (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.commons.support.vector.PgVectorTypeHandler}) as distance
from ai_vector_store_${dimension}
where kb_id = #{kbId}
  and tenant_id = #{tenantId}
  and (1 - (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.commons.support.vector.PgVectorTypeHandler})) > #{minScore}
order by score desc
limit #{topK}

select
    id,
    vector_id,
    content,
    metadata,
    similarity(content, #{keyword}) as score,
    (1 - similarity(content, #{keyword})) as distance
from ai_vector_store_${dimension}
where kb_id = #{kbId}
  and tenant_id = #{tenantId}
  and content % #{keyword}
order by score desc
limit #{topK}

